import React from 'react';
import { Link } from 'react-router-dom';
import '../assets/styles.css';
import '../assets/home-dark.css';
import '../assets/server-theme.css';

import logoNuevo from '../assets/img/logonuevo.png';
import UserMenu from '../components/UserMenu.jsx';

const DISCORD_URL = 'https://discord.rustaco.site';
const STORE_URL = 'https://store.rustaco.co';

export const TICKET_CATEGORIES = [
  { id: 'general', label: 'Soporte general', icon: 'bi-question-circle' },
  { id: 'report', label: 'Reporte de jugador', icon: 'bi-flag' },
  { id: 'appeal', label: 'Apelación de ban', icon: 'bi-shield-exclamation' },
  { id: 'store', label: 'Tienda / Compras', icon: 'bi-cart3' },
  { id: 'bug', label: 'Bug del servidor', icon: 'bi-bug' },
  { id: 'other', label: 'Otro', icon: 'bi-three-dots' },
];

export const TICKET_STATUS = {
  open: { label: 'Abierto', className: 'rw-badge--open', icon: 'bi-envelope-open' },
  answered: { label: 'Respondido', className: 'rw-badge--answered', icon: 'bi-reply' },
  closed: { label: 'Cerrado', className: 'rw-badge--closed', icon: 'bi-check-circle' },
};

export function categoryMeta(id) {
  return TICKET_CATEGORIES.find((cat) => cat.id === id) || TICKET_CATEGORIES[TICKET_CATEGORIES.length - 1];
}

export function statusMeta(status) {
  return TICKET_STATUS[status] || TICKET_STATUS.open;
}

export function formatDate(value) {
  if (!value) return '—';
  const date = new Date(value);
  if (Number.isNaN(date.getTime())) return '—';
  return date.toLocaleString('es-CL', {
    day: '2-digit',
    month: 'short',
    year: 'numeric',
    hour: '2-digit',
    minute: '2-digit',
  });
}

async function readJsonSafe(response) {
  try {
    return await response.json();
  } catch (e) {
    return null;
  }
}

/* ───────────────── Formulario: nuevo ticket ───────────────── */

function NewTicketForm({ onCreated, onCancel }) {
  const [category, setCategory] = React.useState('general');
  const [subject, setSubject] = React.useState('');
  const [message, setMessage] = React.useState('');
  const [sending, setSending] = React.useState(false);
  const [error, setError] = React.useState('');

  const subjectOk = subject.trim().length >= 4;
  const messageOk = message.trim().length >= 10;

  const submit = async (event) => {
    event.preventDefault();
    setError('');
    if (!subjectOk) {
      setError('El asunto debe tener al menos 4 caracteres.');
      return;
    }
    if (!messageOk) {
      setError('El mensaje debe tener al menos 10 caracteres.');
      return;
    }

    setSending(true);
    try {
      const response = await fetch('/api/tickets', {
        method: 'POST',
        credentials: 'include',
        headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify({ category, subject: subject.trim(), message: message.trim() }),
      });
      const data = await readJsonSafe(response);
      if (!response.ok) {
        setError(data?.error || 'No se pudo crear el ticket.');
        return;
      }
      onCreated(data.id);
    } catch (e) {
      setError('Error de conexión. Inténtalo nuevamente.');
    } finally {
      setSending(false);
    }
  };

  return (
    <form className="rw-ticket-form" onSubmit={submit}>
      <div className="rw-form-row">
        <label className="rw-form-field">
          <span className="rw-form-label">Categoría</span>
          <select
            className="rw-input"
            value={category}
            onChange={(event) => setCategory(event.target.value)}
          >
            {TICKET_CATEGORIES.map((cat) => (
              <option key={cat.id} value={cat.id}>{cat.label}</option>
            ))}
          </select>
        </label>
        <label className="rw-form-field rw-form-field--grow">
          <span className="rw-form-label">
            Asunto <em>({subject.trim().length}/100)</em>
          </span>
          <input
            className="rw-input"
            type="text"
            maxLength={100}
            placeholder="Resumen corto del problema"
            value={subject}
            onChange={(event) => setSubject(event.target.value)}
          />
        </label>
      </div>

      <label className="rw-form-field">
        <span className="rw-form-label">
          Mensaje <em>({message.trim().length}/2000)</em>
        </span>
        <textarea
          className="rw-input rw-input--area"
          maxLength={2000}
          rows={6}
          placeholder="Describe tu problema con el máximo detalle posible: qué pasó, cuándo, nombres de jugadores involucrados, evidencia, etc."
          value={message}
          onChange={(event) => setMessage(event.target.value)}
        />
      </label>

      {error && (
        <div className="rw-form-error">
          <i className="bi bi-exclamation-circle" /> {error}
        </div>
      )}

      <div className="rw-form-actions">
        <button
          className="rw-btn rw-btn--primary rw-btn--sm"
          type="submit"
          disabled={sending || !subjectOk || !messageOk}
        >
          {sending ? 'Enviando...' : (
            <>
              <i className="bi bi-send" /> Crear ticket
            </>
          )}
        </button>
        <button className="rw-btn rw-btn--ghost rw-btn--sm" type="button" onClick={onCancel}>
          Cancelar
        </button>
      </div>
    </form>
  );
}

/* ───────────────── Conversación de un ticket ───────────────── */

export function TicketThread({ ticketId, currentUser, onChanged, onBack, allowAdminActions = false }) {
  const [data, setData] = React.useState(null);
  const [loading, setLoading] = React.useState(true);
  const [error, setError] = React.useState('');
  const [reply, setReply] = React.useState('');
  const [sending, setSending] = React.useState(false);
  const [actionError, setActionError] = React.useState('');

  const load = React.useCallback(async () => {
    setLoading(true);
    setError('');
    try {
      const response = await fetch(`/api/tickets/${ticketId}`, { credentials: 'include' });
      const json = await readJsonSafe(response);
      if (!response.ok) {
        setError(json?.error || 'No se pudo cargar el ticket.');
        setData(null);
        return;
      }
      setData(json);
    } catch (e) {
      setError('Error de conexión.');
      setData(null);
    } finally {
      setLoading(false);
    }
  }, [ticketId]);

  React.useEffect(() => {
    load();
  }, [load]);

  const sendReply = async (event) => {
    event.preventDefault();
    if (reply.trim().length < 2 || sending) return;
    setSending(true);
    setActionError('');
    try {
      const response = await fetch(`/api/tickets/${ticketId}/messages`, {
        method: 'POST',
        credentials: 'include',
        headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify({ message: reply.trim() }),
      });
      const json = await readJsonSafe(response);
      if (!response.ok) {
        setActionError(json?.error || 'No se pudo enviar la respuesta.');
        return;
      }
      setReply('');
      await load();
      if (onChanged) onChanged();
    } catch (e) {
      setActionError('Error de conexión.');
    } finally {
      setSending(false);
    }
  };

  const closeTicket = async () => {
    setActionError('');
    try {
      const response = await fetch(`/api/tickets/${ticketId}/close`, {
        method: 'POST',
        credentials: 'include',
      });
      const json = await readJsonSafe(response);
      if (!response.ok) {
        setActionError(json?.error || 'No se pudo cerrar el ticket.');
        return;
      }
      await load();
      if (onChanged) onChanged();
    } catch (e) {
      setActionError('Error de conexión.');
    }
  };

  const setStatus = async (status) => {
    setActionError('');
    try {
      const response = await fetch(`/api/admin/tickets/${ticketId}/status`, {
        method: 'POST',
        credentials: 'include',
        headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify({ status }),
      });
      const json = await readJsonSafe(response);
      if (!response.ok) {
        setActionError(json?.error || 'No se pudo actualizar el estado.');
        return;
      }
      await load();
      if (onChanged) onChanged();
    } catch (e) {
      setActionError('Error de conexión.');
    }
  };

  if (loading) {
    return (
      <div className="rw-lb-state" style={{ border: 'none' }}>
        <span className="rw-spinner" />
        <div>Cargando ticket...</div>
      </div>
    );
  }

  if (error || !data) {
    return (
      <div>
        <div className="rw-lb-state rw-lb-state--error">{error || 'Ticket no disponible.'}</div>
        {onBack && (
          <button className="rw-btn rw-btn--ghost rw-btn--sm" style={{ marginTop: 12 }} onClick={onBack} type="button">
            <i className="bi bi-arrow-left" /> Volver
          </button>
        )}
      </div>
    );
  }

  const { ticket, messages } = data;
  const status = statusMeta(ticket.Status);
  const cat = categoryMeta(ticket.Category);
  const isClosed = ticket.Status === 'closed';

  return (
    <div className="rw-thread">
      <div className="rw-thread-head">
        {onBack && (
          <button className="rw-btn rw-btn--ghost rw-btn--sm" onClick={onBack} type="button">
            <i className="bi bi-arrow-left" /> Volver
          </button>
        )}
        <div className="rw-thread-title">
          <h3>
            <span className="rw-thread-id">#{ticket.Id}</span> {ticket.Subject}
          </h3>
          <div className="rw-thread-meta">
            <span className={`rw-badge ${status.className}`}>
              <i className={`bi ${status.icon}`} /> {status.label}
            </span>
            <span className="rw-badge rw-badge--cat">
              <i className={`bi ${cat.icon}`} /> {cat.label}
            </span>
            <span className="rw-thread-date">Creado: {formatDate(ticket.CreatedAt)}</span>
          </div>
        </div>
      </div>

      <div className="rw-thread-messages">
        {messages.map((msg) => {
          const mine = currentUser && String(msg.SteamId) === String(currentUser.steamid);
          return (
            <div
              key={msg.Id}
              className={`rw-msg ${msg.IsAdmin ? 'rw-msg--admin' : ''} ${mine ? 'rw-msg--mine' : ''}`}
            >
              <div className="rw-msg-avatar">
                {msg.Avatar ? <img src={msg.Avatar} alt="" /> : <i className="bi bi-person-circle" />}
              </div>
              <div className="rw-msg-content">
                <div className="rw-msg-author">
                  <strong>{msg.UserName}</strong>
                  {Boolean(msg.IsAdmin) && (
                    <span className="rw-badge rw-badge--staff">
                      <i className="bi bi-shield-fill-check" /> Staff
                    </span>
                  )}
                  <span className="rw-msg-date">{formatDate(msg.CreatedAt)}</span>
                </div>
                <p>{msg.Body}</p>
              </div>
            </div>
          );
        })}
      </div>

      {actionError && (
        <div className="rw-form-error">
          <i className="bi bi-exclamation-circle" /> {actionError}
        </div>
      )}

      {!isClosed || allowAdminActions ? (
        <form className="rw-thread-reply" onSubmit={sendReply}>
          <textarea
            className="rw-input rw-input--area"
            rows={3}
            maxLength={2000}
            placeholder={isClosed ? 'Responder reabre la conversación (staff)...' : 'Escribe tu respuesta...'}
            value={reply}
            onChange={(event) => setReply(event.target.value)}
          />
          <div className="rw-form-actions">
            <button
              className="rw-btn rw-btn--primary rw-btn--sm"
              type="submit"
              disabled={sending || reply.trim().length < 2}
            >
              {sending ? 'Enviando...' : (
                <>
                  <i className="bi bi-send" /> Responder
                </>
              )}
            </button>
            {!isClosed && (
              <button className="rw-btn rw-btn--ghost rw-btn--sm" type="button" onClick={closeTicket}>
                <i className="bi bi-check-circle" /> Cerrar ticket
              </button>
            )}
            {allowAdminActions && (
              <span className="rw-thread-adminactions">
                {ticket.Status !== 'open' && (
                  <button className="rw-btn rw-btn--ghost rw-btn--sm" type="button" onClick={() => setStatus('open')}>
                    Reabrir
                  </button>
                )}
                {ticket.Status !== 'answered' && (
                  <button className="rw-btn rw-btn--ghost rw-btn--sm" type="button" onClick={() => setStatus('answered')}>
                    Marcar respondido
                  </button>
                )}
              </span>
            )}
          </div>
        </form>
      ) : (
        <div className="rw-thread-closed">
          <i className="bi bi-lock" /> Este ticket está cerrado. Si necesitas más ayuda, crea uno nuevo.
        </div>
      )}
    </div>
  );
}

